/* Pure quiz rules, shared by the browser and dependency-free Node tests. */
const QuizCore = (() => {
  const refs = {
    devops: 'https://docs.github.com/en/actions/get-started/understand-github-actions',
    cloud: 'https://docs.aws.amazon.com/IAM/latest/UserGuide/best-practices.html',
    platform: 'https://kubernetes.io/docs/concepts/overview/'
  };
  const rows = [
    ['devops','foundation','What is the main purpose of continuous integration?',['Automatically merge every pull request','Build and test changes frequently','Replace version control','Eliminate code reviews'],1,'CI detects integration problems early by running automated checks on changes.'],
    ['devops','foundation','Which Git command creates and switches to a new dev branch?',['git push dev','git merge dev','git switch -c dev','git status dev'],2,'git switch -c creates a branch at the current commit and checks it out.'],
    ['devops','foundation','A required test fails. What should the delivery pipeline do?',['Publish anyway','Disable all tests','Delete the repository','Block dependent release stages'],3,'A failing quality gate should stop dependent publishing or deployment jobs.'],
    ['devops','foundation','What does an image registry store?',['Container images','Only running processes','DNS queries','Source-control branches'],0,'A registry stores images that container runtimes can pull and run.','https://docs.docker.com/get-started/docker-concepts/the-basics/what-is-a-registry/'],
    ['devops','advanced','How do you ensure production uses the exact container artifact tested in staging?',['Rebuild with the latest tag','Promote the same image digest','Rename the Dockerfile','Skip the production scan'],1,'A digest identifies image content. Rebuilding or using a mutable tag can select different content.','https://docs.docker.com/dhi/core-concepts/digests/'],
    ['devops','advanced','A bad release commit is already shared. Which approach preserves a reviewable rollback history?',['Delete .git','Force-reset everyone’s branch','Create a revert commit','Edit the registry tag silently'],2,'Revert records a new inverse change, preserving the history other collaborators already have.','https://git-scm.com/docs/git-revert'],
    ['devops','advanced','An external contributor opens a pull request. How should its CI job handle deployment credentials?',['Expose the production token','Print credentials for debugging','Give the job administrator access','Do not expose deployment credentials to untrusted code'],3,'Untrusted pull request code must not receive privileged deployment credentials.','https://docs.github.com/en/actions/security-for-github-actions/security-guides/security-hardening-for-github-actions'],
    ['devops','advanced','Why can changing a PHP CLI alternative leave the website’s PHP version unchanged?',['Nginx still points to its configured FPM listener','PHP has no command-line version','Nginx runs all PHP versions at once','DNS chooses the PHP version'],0,'CLI and FPM are separate execution paths. Nginx sends PHP requests to the FastCGI listener configured in fastcgi_pass.','https://nginx.org/en/docs/http/ngx_http_fastcgi_module.html#fastcgi_pass'],
    ['cloud','foundation','What does least privilege mean?',['Everyone is an administrator','Only the permissions needed for the task','No authentication is required','All resources are public'],1,'Grant the smallest useful set of permissions for the task and review access over time.'],
    ['cloud','foundation','What is the purpose of a load balancer?',['Store source code','Create passwords','Distribute incoming traffic across targets','Replace all backups'],2,'A load balancer routes requests across configured targets, often using health checks.','https://docs.aws.amazon.com/elasticloadbalancing/latest/userguide/what-is-load-balancing.html'],
    ['cloud','foundation','Which storage model fits files addressed by a bucket and object key?',['CPU cache','Process memory','Network route table','Object storage'],3,'Object storage exposes objects inside buckets rather than a traditional block device.','https://docs.aws.amazon.com/AmazonS3/latest/userguide/Welcome.html'],
    ['cloud','foundation','What does DNS primarily do for a website request?',['Resolve a domain name to records such as IP addresses','Execute the application','Encrypt the database','Scan a container'],0,'DNS resolves names; connecting, negotiating TLS, and serving HTTP are separate steps.','https://www.cloudflare.com/learning/dns/what-is-dns/'],
    ['cloud','advanced','How should an AWS workload obtain AWS permissions when supported?',['Embed root access keys in source','Use an IAM role with temporary credentials','Share a developer’s permanent password','Disable access checks'],1,'Workload roles supply temporary credentials without embedding long-lived keys in code.'],
    ['cloud','advanced','Does marking a Terraform value sensitive automatically encrypt the state file?',['Yes, with a new key','Yes, but only for outputs','No; state storage needs separate protection','State never contains values'],2,'Sensitive redacts normal output. Values may remain in state, so protect backend access and storage.','https://developer.hashicorp.com/terraform/language/manage-sensitive-data'],
    ['cloud','advanced','What does a recovery point objective (RPO) describe?',['Time to deploy a new feature','Maximum CPU utilization','Length of a Git branch name','The acceptable data-loss window'],3,'RPO concerns how much recent data can be lost. RTO concerns the recovery-time objective.','https://docs.aws.amazon.com/wellarchitected/latest/reliability-pillar/plan-for-disaster-recovery-dr.html'],
    ['cloud','advanced','An application must tolerate loss of one availability zone. Which design helps?',['Healthy replicas across multiple zones with traffic failover','All replicas on one server','One larger disk without backups','One zone with a longer timeout'],0,'Spreading replicas across failure domains reduces exposure to a zone failure; traffic and data design must support failover.','https://docs.aws.amazon.com/wellarchitected/latest/reliability-pillar/use-fault-isolation-to-protect-your-workload.html'],
    ['platform','foundation','What is the smallest deployable computing unit in Kubernetes?',['Region','Pod','Git commit','Dashboard'],1,'A Pod groups one or more containers that share networking and selected resources.','https://kubernetes.io/docs/concepts/workloads/pods/'],
    ['platform','foundation','Which probe controls whether a Pod is ready to receive service traffic?',['Liveness only','CPU usage probe','Readiness probe','Image scan'],2,'Readiness signals traffic eligibility; liveness can trigger a restart after failure thresholds.','https://kubernetes.io/docs/concepts/workloads/pods/probes/'],
    ['platform','foundation','What is a primary use of Prometheus?',['Hosting Git repositories','Registering domains','Building images','Collecting and querying metrics'],3,'Prometheus collects time-series metrics and supports queries and alerting rules.','https://prometheus.io/docs/introduction/overview/'],
    ['platform','foundation','Which resource gives a stable network abstraction over a changing set of Pods?',['Service','Commit','Dockerfile','Local shell alias'],0,'A Service provides a network abstraction for reaching selected backends as Pods change.','https://kubernetes.io/docs/concepts/services-networking/service/'],
    ['platform','advanced','A slow-starting application is killed by liveness checks during initialization. What is a suitable fix?',['Remove all health checks forever','Use a properly configured startup probe','Increase DNS TTL','Rename the deployment'],1,'A startup probe gives initialization its own budget and delays readiness and liveness checks until it succeeds.','https://kubernetes.io/docs/concepts/workloads/pods/probes/'],
    ['platform','advanced','What does a Kubernetes CPU limit typically cause when a container tries to exceed it?',['Automatic Git rollback','Unlimited burst with no restriction','CPU throttling','Guaranteed node shutdown'],2,'CPU limits are enforced through throttling. Memory-limit behavior differs and can involve termination.','https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/'],
    ['platform','advanced','An SLO requires 99.9% successful requests. What is the error budget for 1,000,000 eligible requests?',['100,000 failures','10 failures','Zero failures','1,000 failures'],3,'The allowed failure fraction is 0.1%. Multiplying 1,000,000 by 0.001 gives 1,000 requests.','https://sre.google/sre-book/service-level-objectives/'],
    ['platform','advanced','Argo CD reports Synced. What should you verify next?',['Application health and actual user-facing behavior','Nothing; every response must be correct','Whether Git can be deleted','Whether tests can be removed'],0,'Sync says live configuration matches desired state. Health and functional correctness require additional evidence.','https://argo-cd.readthedocs.io/en/stable/core_concepts/']
  ];
  const questions = rows.map((r,i)=>({id:`q${i+1}`,topic:r[0],difficulty:r[1],prompt:r[2],options:r[3],correct:r[4],explanation:r[5],source:r[6]||refs[r[0]]}));
  function select(topic='all',difficulty='all',random=Math.random){const pool=questions.filter(q=>(topic==='all'||q.topic===topic)&&(difficulty==='all'||q.difficulty===difficulty));for(let i=pool.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}return pool.slice(0,Math.min(5,pool.length));}
  function create(list){return {questions:list,index:0,answers:[],score:0,streak:0,bestStreak:0,finished:false};}
  function answer(game,choice){if(game.finished||game.answers.length>game.index)return false;const q=game.questions[game.index];if(!q||!Number.isInteger(choice)||choice<0||choice>=q.options.length)return false;const correct=choice===q.correct;game.streak=correct?game.streak+1:0;game.bestStreak=Math.max(game.bestStreak,game.streak);const points=correct?100+Math.min(game.streak-1,4)*25:0;game.score+=points;game.answers.push({choice,correct,points});return true;}
  function next(game){if(game.finished||game.answers.length<=game.index)return false;if(game.index===game.questions.length-1)game.finished=true;else game.index++;return true;}
  function summarize(game){return {correct:game.answers.filter(a=>a.correct).length,total:game.questions.length,score:game.score,bestStreak:game.bestStreak};}
  return {questions,select,create,answer,next,summarize};
})();
if(typeof module!=='undefined')module.exports=QuizCore;
